/**
 * Uzbekistan microdistricts (mahallas / massivs / neighbourhoods) registry —
 * single source of truth for the `microdistrict` autocomplete in the seller
 * listing form.
 *
 * Mirrors the {@link ./metroStations} pattern: a flat registry where every
 * entry is pinned to a district key from {@link ./regions} so the
 * район→микрорайон cascade can filter suggestions by `form.values.district`
 * (district keys are unique across regions). The field stays free-text, so a
 * seller can type a name that is not in the list; entries only drive hints.
 *
 * Each entry carries the name in three locales so the picker and the listing
 * view render in the active UI language ({@link microdistrictName}):
 *   - `name`     — Russian (OSM name:ru)
 *   - `nameUzLatn`/`nameUzCyrl` — Uzbek. Where OSM has a real `name:uz` it is
 *     used (Latin) and converted to Cyrillic; otherwise the names are machine
 *     transliterated from Russian (a small glossary handles mahalla / massiv /
 *     mikrorayon / kvartal), so some Uzbek variants are approximate.
 *
 * Data provenance: place=suburb|neighbourhood|quarter nodes inside Uzbekistan
 * (OpenStreetMap via Overpass API), assigned to a district by point-in-polygon
 * against OSM admin_level=6 boundaries. Coordinates are WGS-84 (lat/lng).
 *
 * 895 entries across 59 districts in 14 regions. Coverage reflects what
 * OSM currently tags; many rural districts have few or no neighbourhood nodes.
 */

export type AppLanguage = "ru" | "uz-latn" | "uz-cyrl" | "uz";

export interface Microdistrict {
	/** Display name in Russian (OSM name:ru). */
	name: string;
	/** Uzbek (Latin) name — real OSM name:uz where available, else machine. */
	nameUzLatn: string;
	/** Uzbek (Cyrillic) name — derived from the Uzbek-Latin / Russian name. */
	nameUzCyrl: string;
	/** District key from {@link ./regions} (REGIONS) the entry sits in. */
	district: string;
	/** WGS-84 latitude. */
	lat: number;
	/** WGS-84 longitude. */
	lng: number;
}

/** Pick the microdistrict name matching the active UI language. Robust to
 *  casing / region-tag variants (e.g. "uz-Latn", "uz-Cyrl", "uz"). */
export function microdistrictName(m: Microdistrict, lang: string): string {
	const l = (lang || "").toLowerCase();
	if (l.includes("cyrl")) return m.nameUzCyrl;
	if (l.startsWith("uz")) return m.nameUzLatn;
	return m.name;
}

/**
 * Resolve a stored microdistrict value to the active language. Looks the value
 * up across all three locale variants; returns the localized name if found, or
 * the original value unchanged (free-text entries the seller typed by hand).
 */
export function localizeMicrodistrict(value: string, lang: string): string {
	if (!value) return value;
	const hit = MICRODISTRICTS.find(
		(m) =>
			m.name === value || m.nameUzLatn === value || m.nameUzCyrl === value,
	);
	return hit ? microdistrictName(hit, lang) : value;
}

